#include <stddef.h>
#include <stdlib.h>

int parse_image(const uint8_t *data, size_t size);

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
 if (size < 4 || size > (1 << 20)) return 0;
 uint8_t *buf = malloc(size);
 if (!buf) return 0;
 memcpy(buf, data, size);
 parse_image(buf, size);
 free(buf);
 return 0;
}
